"""Static shells and catalogue links for the Y9 Gas Laws practice games."""
from pathlib import Path
import json
ROOT=Path(__file__).resolve().parent.parent
folder=ROOT/'activities/y9/science/gas-laws/games'
P='../../../../../'
def shell(title,intro,body,kind=''):
 return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#f8f7ff"><title>{title} | Y9 Gas Laws | Learning Lab</title><meta name="description" content="{intro}"><link rel="icon" type="image/png" href="{P}assets/brand/learning-lab-logo.png"><link rel="stylesheet" href="{P}platform.css"><link rel="stylesheet" href="{P}assets/brand/brand.css?v=1"><link rel="stylesheet" href="games.css?v=1"><link rel="stylesheet" href="{P}assets/desktop-layout.css?v=desktop-1">{f'<script type="module" src="games.js?v=1"></script>' if kind else ''}</head><body {f'data-game="{kind}"' if kind else ''}><a class="skip-link" href="#main">Skip to game</a><header class="site-header"><a class="wordmark" href="{P}index.html"><img class="brand-logo" src="{P}assets/brand/learning-lab-logo.png" width="46" height="46" alt=""><span>learning<span class="wordmark-light">lab</span><small>A PLACE FOR CURIOUS MINDS</small></span></a><nav aria-label="Main navigation"><a href="../index.html#games">Gas laws lesson</a><a href="./">Games</a><a href="../revision.html">Revision simulator</a></nav></header><main id="main" tabindex="-1"><nav class="breadcrumbs" aria-label="Breadcrumb"><ol><li><a href="{P}index.html#/years/y9/science">Y9 Science</a></li><li><a href="../index.html">Gas laws</a></li><li><a href="./">Games</a></li><li><span aria-current="page">{title}</span></li></ol></nav><section class="games-hero"><span class="game-tag">YEAR 9 SCIENCE · LEARN THROUGH PLAY</span><h1>{title}</h1><p>{intro}</p><nav class="game-tabs" aria-label="Choose a game"><a href="picture-law.html" {'aria-current="page"' if kind=='picture' else ''}>01 · Name That Gas Law</a><a href="mystery-word.html" {'aria-current="page"' if kind=='word' else ''}>02 · Mystery Word</a></nav></section>{body}<p class="games-note">These are practice games. Scores stay on this page and are not sent to the teacher dashboard. For a recorded Test yourself quiz, open the <a href="../revision.html">revision simulator</a>.</p><noscript><p class="games-note">Enable JavaScript to play. You can still read the <a href="../index.html#applications">gas-law examples and their model conditions</a>.</p></noscript></main><footer class="site-footer"><a class="footer-brand" href="{P}index.html"><img class="brand-logo" src="{P}assets/brand/learning-lab-logo.png" width="34" height="34" alt="">learning<span>lab</span></a><p>Notice the pattern. Choose your words. Explain why.</p><a href="../index.html#games">Back to the lesson →</a></footer></body></html>'''
cards='''<div class="game-hub"><a class="hub-card picture-hub" href="picture-law.html"><div class="hub-art"><img src="images/gas-law-cards.png" width="1254" height="1254" alt="Nine colourful everyday gas-law examples"></div><div><span class="game-tag">GAME 01 · PICTURE DETECTIVE</span><h2>Name That Gas Law</h2><p>Study one picture, choose the two changing quantities and name the law. Watch out for what stays constant!</p><span class="play-link">Play the picture challenge →</span></div></a><a class="hub-card word-hub" href="mystery-word.html"><div class="word-art" aria-hidden="true"><span>?</span><b>CLUE → THINK → DISCOVER</b></div><div><span class="game-tag">GAME 02 · WORD DETECTIVE</span><h2>Mystery Word</h2><p>Read the clue and identify the science word. Use “You won’t say” to uncover common mix-ups and why they don’t fit.</p><span class="play-link">Solve a mystery word →</span></div></a></div>'''
(folder/'index.html').write_text(shell('Gas Laws Games','Two colourful challenges to connect everyday pictures, scientific quantities and the words we use to explain gases.',cards))
(folder/'picture-law.html').write_text(shell('Name That Gas Law','One picture, two changing quantities, one law. Read the model conditions, select pressure, volume or temperature, then match the gas law.','<div id="game-app" aria-label="Picture gas-law game"><p role="status">Preparing your picture cards…</p></div>','picture'))
(folder/'mystery-word.html').write_text(shell('Mystery Word','Read the description and name the gas-unit word. Open “You won’t say” for common mix-ups and explanations that help you choose precisely.','<div id="game-app" aria-label="Mystery Word game"><p role="status">Preparing your mystery clues…</p></div>','word'))
# Add the two discovery links without changing the primary gas-laws activity.
p=ROOT/'catalog.json';catalog=json.loads(p.read_text());topic=next(t for y in catalog['years'] if y['id']=='y9' for s in y['subjects'] if s['id']=='science' for t in s['topics'] if t['id']=='gas-laws')
topic['activities']=[a for a in topic['activities'] if a['id'] not in ['gas-laws-picture-game','gas-laws-word-game']]
for key,title,desc,href in [('picture','Name That Gas Law','Match nine everyday pictures to the changing quantities and their gas law.','picture-law.html'),('word','Mystery Word','Solve science clues and untangle commonly confused words with explanations.','mystery-word.html')]:
 topic['activities'].append(dict(id=f'gas-laws-{key}-game',title=title,description=desc,format='Picture game' if key=='picture' else 'Vocabulary game',duration='5–10 minutes',image='activities/y9/science/gas-laws/games/images/gas-law-cards.png',href='activities/y9/science/gas-laws/games/'+href))
p.write_text(json.dumps(catalog,ensure_ascii=False,indent=2)+'\n')
print('Built Gas Laws game hub, picture game and Mystery Word; added two catalogue links.')
